declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notificaciones — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:760px;margin:auto;padding:86px 14px 36px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:18px;box-shadow:0 8px 26px #0f172a0a}.ey{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.09em;color:#64748b}.title{font-size:28px;font-weight:900;margin:6px 0 8px}.sub{color:#64748b;line-height:1.5;margin-bottom:18px}.status{padding:12px;border-radius:12px;background:#f8fafc;margin-bottom:14px;font-weight:800}.btn{width:100%;border:0;border-radius:12px;padding:14px;font-size:15px;font-weight:900;background:#172033;color:#fff}.btn.off{background:#e2e8f0;color:#334155;margin-top:8px}.note{font-size:12px;color:#64748b;line-height:1.5;margin-top:14px}</style></head><body><main class="wrap"><section class="card"><div class="ey">Franky · ADMIN</div><div class="title">Notificaciones push</div><div class="sub">Activa este dispositivo para recibir avisos importantes aunque Franky esté cerrado. Por ahora se enviarán únicamente nuevos registros públicos.</div><div id="status" class="status">Comprobando…</div><button id="activar" class="btn">Activar notificaciones en este dispositivo</button><button id="desactivar" class="btn off">Desactivar en este dispositivo</button><div class="note">Necesitas abrir esta pantalla mediante HTTPS. Cada ADMIN puede activar varios teléfonos o navegadores.</div></section></main><script>
const st=document.getElementById('status'),on=document.getElementById('activar'),off=document.getElementById('desactivar');function b64(s){const pad='='.repeat((4-s.length%4)%4),base=(s+pad).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a}async function reg(){if(!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Este navegador no soporta Web Push.');return await navigator.serviceWorker.register('/service-worker.js')}async function current(){const r=await reg();return await r.pushManager.getSubscription()}async function paint(){try{const s=await current();st.textContent=s?'✅ Notificaciones activas en este dispositivo':'Notificaciones desactivadas en este dispositivo';off.style.display=s?'block':'none'}catch(e){st.textContent=e.message;off.style.display='none'}}on.onclick=async()=>{try{if(location.protocol!=='https:')throw Error('Abre Franky por HTTPS para activar notificaciones.');const p=await Notification.requestPermission();if(p!=='granted')throw Error('Permiso de notificaciones no concedido.');const kr=await fetch('/api/push.php',{cache:'no-store'}),kd=await kr.json();if(!kr.ok||!kd.ok)throw Error(kd.error||'No se pudo obtener la clave push');const r=await reg();let s=await r.pushManager.getSubscription();if(!s)s=await r.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:b64(kd.publicKey)});const rr=await fetch('/api/push.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:s.toJSON()})}),d=await rr.json();if(!rr.ok||!d.ok)throw Error(d.error||'No se pudo guardar la suscripción');await paint()}catch(e){st.textContent='⚠️ '+e.message}};off.onclick=async()=>{try{const s=await current();if(s){await fetch('/api/push.php',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:s.endpoint})});await s.unsubscribe()}await paint()}catch(e){st.textContent='⚠️ '+e.message}};paint();
</script></body></html>